import { DashboardOutlined, PartitionOutlined } from '@ant-design/icons';
import { Layout, Menu, Typography } from 'antd';
import type { MenuProps } from 'antd';
import { useMemo } from 'react';
import { Outlet, useLocation, useNavigate } from 'react-router-dom';

const { Header, Sider, Content } = Layout;

const AppLayout = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const menuItems = useMemo(
    () => [
      { key: 'dashboard', label: 'Dashboard', icon: <DashboardOutlined />, path: '/subsystems' },
      { key: 'subsystems', label: 'Subsystems', icon: <PartitionOutlined />, path: '/subsystems' },
    ],
    [],
  );

  const selectedKey = location.pathname.startsWith('/subsystems') ? 'subsystems' : 'dashboard';

  const onMenuClick: MenuProps['onClick'] = ({ key }) => {
    const target = menuItems.find((item) => item.key === key);
    if (target) {
      navigate(target.path);
    }
  };

  return (
    <Layout style={{ minHeight: '100vh' }}>
      <Sider breakpoint="lg" collapsedWidth={64} width={220} style={{ background: '#001529' }}>
        <div
          style={{
