import { ReloadOutlined } from '@ant-design/icons';
import {
  Alert,
  Button,
  Card,
  Input,
  Progress,
  Space,
  Statistic,
  Table,
  Tag,
  Typography,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { axiosInstance } from '../api/client';
import type { Subsystem } from '../api/types';

const formatDate = (value: string | null) => {
  if (!value) return 'N/A';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return new Intl.DateTimeFormat('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(date);
};

const SubsystemListPage = () => {
  const navigate = useNavigate();
  const [subsystems, setSubsystems] = useState<Subsystem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchValue, setSearchValue] = useState('');

  const loadSubsystems = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await axiosInstance.get<Subsystem[]>('/subsystems/');
      setSubsystems(response.data);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load subsystems';
      setError(message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadSubsystems();
  }, [loadSubsystems]);

  const filteredSubsystems = useMemo(() => {
    const term = searchValue.trim().toLowerCase();
    if (!term) {
      return subsystems;
    }

    return subsystems.filter((item) => {
      return [
        item.sys_code,
        item.subsys_code,
        item.name ?? '',
        item.discipline ?? '',
      ]
        .join(' ')
        .toLowerCase()
        .includes(term);
    });
  }, [searchValue, subsystems]);

  const totals = useMemo(() => {
    return subsystems.reduce(
      (
        acc,
        { tag_total, mcr_total, mcr_closed, tag_with_punch: tagsWithPunch },
      ) => {
        acc.tag_total += tag_total ?? 0;
        acc.mcr_total += mcr_total ?? 0;
        acc.mcr_closed += mcr_closed ?? 0;
        acc.tag_with_punch += tagsWithPunch ?? 0;
        return acc;
      },
      { tag_total: 0, mcr_total: 0, mcr_closed: 0, tag_with_punch: 0 },
    );
  }, [subsystems]);

  const columns: ColumnsType<Subsystem> = [
    {
      title: 'System',
      key: 'system',
      render: (_, record) => (
        <Space direction="vertical" size={0}>
          <Typography.Text strong>{record.sys_code}</Typography.Text>
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            Subsystem {record.subsys_code}
          </Typography.Text>
        </Space>
      ),
    },
    {
      title: 'Name',
      dataIndex: 'name',
      render: (value: string | null) => value ?? '—',
    },
    {
      title: 'Discipline',
      dataIndex: 'discipline',
      render: (value: string | null) =>
        value ? <Tag color="blue">{value}</Tag> : <Typography.Text type="secondary">N/A</Typography.Text>,
    },
    {
      title: 'Tags',
      dataIndex: 'tag_total',
      sorter: (a, b) => a.tag_total - b.tag_total,
    },
    {
      title: 'MCR Progress',
      key: 'mcr',
      render: (_, record) => {
        const total = record.mcr_total || 0;
        const closed = record.mcr_closed || 0;
        const percent = total ? Math.round((closed / total) * 100) : 0;
        return (
          <Space direction="vertical" size={0}>
            <Typography.Text>
              {closed}/{total} closed
            </Typography.Text>
            <Progress percent={percent} size="small" status="active" />
          </Space>
        );
      },
    },
    {
      title: 'Tags with Punch',
      dataIndex: 'tag_with_punch',
      sorter: (a, b) => a.tag_with_punch - b.tag_with_punch,
    },
    {
      title: 'Last Update',
      dataIndex: 'last_update',
      render: (value: string | null) => formatDate(value),
    },
  ];

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <Typography.Title level={3} style={{ marginBottom: 0 }}>
        Subsystems Overview
      </Typography.Title>

      <Card>
        <Space size="large" wrap>
          <Statistic title="Total Tags" value={totals.tag_total} />
          <Statistic
            title="MCR Closed"
            value={totals.mcr_total ? ((totals.mcr_closed / totals.mcr_total) * 100).toFixed(1) : '0.0'}
            suffix="%"
          />
          <Statistic title="Tags with Punch" value={totals.tag_with_punch} />
        </Space>
      </Card>

      <Card
        title="Subsystems"
        extra={
          <Space>
            <Input.Search
              placeholder="Search by name, system or discipline"
              allowClear
              value={searchValue}
              onChange={(event) => setSearchValue(event.target.value)}
              style={{ width: 280 }}
            />
            <Button icon={<ReloadOutlined />} onClick={() => void loadSubsystems()} loading={loading}>
              Refresh
            </Button>
          </Space>
        }
      >
        {error && (
          <Alert
            type="error"
            message="Unable to load subsystems"
            description={error}
            showIcon
            style={{ marginBottom: 16 }}
          />
        )}
        <Table<Subsystem>
          rowKey={(record) => `${record.sys_code}-${record.subsys_code}`}
          columns={columns}
          dataSource={filteredSubsystems}
          loading={loading}
          pagination={{ pageSize: 10 }}
          onRow={(record) => ({
            onClick: () =>
              navigate(`/subsystems/${encodeURIComponent(record.sys_code)}/${encodeURIComponent(record.subsys_code)}`),
            style: { cursor: 'pointer' },
          })}
        />
      </Card>
    </Space>
  );
};

