      setTags(response.data);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load tags';
      setError(message);
    } finally {
      setLoading(false);
    }
  }, [sysCode, subsysCode]);

  useEffect(() => {
    void loadTags();
  }, [loadTags]);

  if (!sysCode || !subsysCode) {
