      {
        title: 'Punch Code',
        dataIndex: 'punch_code',
        render: (value: string) => value,
      },
      {
        title: 'Description',
        key: 'description',
        render: (_, record) => record.desc_en ?? record.desc_cn ?? '—',
      },
      {
        title: 'Classification',
        dataIndex: 'ab_class',
        render: (value: string | null) => value ?? '—',
