import {
  Alert,
  Breadcrumb,
  Button,
  Card,
  Input,
  Progress,
  Space,
  Statistic,
  Table,
  Tag,
  Typography,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, Navigate, useNavigate, useParams } from 'react-router-dom';
import { axiosInstance } from '../api/client';
import type { TagWithStats } from '../api/types';

const SubsystemDetailPage = () => {
  const { sys_code: sysCodeParam, subsys_code: subsysCodeParam } = useParams();
  const navigate = useNavigate();
  const [tags, setTags] = useState<TagWithStats[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');

  const loadTags = useCallback(async () => {
    if (!sysCodeParam || !subsysCodeParam) return;
    try {
      setLoading(true);
      setError(null);
      const response = await axiosInstance.get<TagWithStats[]>(
        `/subsystems/${encodeURIComponent(sysCodeParam)}/${encodeURIComponent(subsysCodeParam)}/tags`,
      );
      setTags(response.data);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load tags';
      setError(message);
    } finally {
      setLoading(false);
    }
  }, [sysCodeParam, subsysCodeParam]);

  useEffect(() => {
    void loadTags();
  }, [loadTags]);

  if (!sysCodeParam || !subsysCodeParam) {
    return <Navigate to="/subsystems" replace />;
  }

  const sysCode = sysCodeParam;
  const subsysCode = subsysCodeParam;

  const filteredTags = useMemo(() => {
    const term = search.trim().toLowerCase();
    if (!term) {
      return tags;
    }
    return tags.filter((tag) => {
      return [
        tag.tag_no,
        tag.description ?? '',
        tag.location ?? '',
        tag.discipline ?? '',
      ]
        .join(' ')
        .toLowerCase()
        .includes(term);
    });
  }, [search, tags]);

  const summary = useMemo(() => {
    return tags.reduce(
      (
        acc,
        { mcr_count, mcr_closed_count, punch_count, punch_open_count },
      ) => {
        acc.mcrTotal += mcr_count;
        acc.mcrClosed += mcr_closed_count;
        acc.punchTotal += punch_count;
        acc.punchOpen += punch_open_count;
        acc.tagTotal += 1;
        return acc;
      },
      { mcrTotal: 0, mcrClosed: 0, punchTotal: 0, punchOpen: 0, tagTotal: 0 },
    );
  }, [tags]);

  const columns: ColumnsType<TagWithStats> = [
    {
      title: 'Tag',
      dataIndex: 'tag_no',
      render: (value: string, record) => (
        <Space direction="vertical" size={0}>
          <Typography.Text strong>{value}</Typography.Text>
          <Typography.Text type="secondary">{record.description ?? 'N/A'}</Typography.Text>
        </Space>
      ),
    },
    {
      title: 'Discipline',
      dataIndex: 'discipline',
      render: (value: string | null) =>
        value ? <Tag color="cyan">{value}</Tag> : <Typography.Text type="secondary">N/A</Typography.Text>,
    },
    {
      title: 'Location',
      dataIndex: 'location',
      render: (value: string | null) => value ?? 'N/A',
    },
    {
      title: 'Scope',
      dataIndex: 'scope',
      render: (value: string | null) => value ?? 'N/A',
    },
    {
      title: 'MCR',
      key: 'mcr',
      render: (_, record) => {
        const percent = record.mcr_count
          ? Math.round((record.mcr_closed_count / record.mcr_count) * 100)
          : 0;
        return (
          <Space direction="vertical" size={0}>
            <Typography.Text>
              {record.mcr_closed_count}/{record.mcr_count}
            </Typography.Text>
            <Progress percent={percent} size="small" status="active" />
          </Space>
        );
      },
    },
    {
      title: 'Punch Status',
      key: 'punch',
      render: (_, record) => (
        <Space direction="vertical" size={0}>
          <Typography.Text>
            Open {record.punch_open_count} / Total {record.punch_count}
          </Typography.Text>
          <Progress
            percent={record.punch_count ? Math.round(((record.punch_count - record.punch_open_count) / record.punch_count) * 100) : 0}
            size="small"
            strokeColor="#f5222d"
          />
        </Space>
      ),
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Button
          type="link"
          onClick={() =>
            navigate(
              `/tags/${encodeURIComponent(record.sys_code)}/${encodeURIComponent(record.subsys_code)}/${encodeURIComponent(record.tag_no)}`,
            )
          }
        >
          View Details
        </Button>
      ),
    },
  ];

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      <Breadcrumb
        items={[
          { title: <Link to="/subsystems">Subsystems</Link> },
          { title: `${sysCode} / ${subsysCode}` },
        ]}
      />

      <Typography.Title level={3} style={{ margin: 0 }}>
        Subsystem {sysCode}-{subsysCode}
      </Typography.Title>

      <Card>
        <Space size="large" wrap>
          <Statistic title="Tags" value={summary.tagTotal} />
          <Statistic
            title="MCR Closed"
            value={summary.mcrTotal ? ((summary.mcrClosed / summary.mcrTotal) * 100).toFixed(1) : '0.0'}
            suffix="%"
          />
          <Statistic title="Punch Open" value={summary.punchOpen} />
        </Space>
      </Card>

      <Card
        title="Tags"
        extra={
          <Input.Search
            placeholder="Search tags"
            allowClear
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            style={{ width: 260 }}
          />
        }
      >
        {error && (
          <Alert
            type="error"
            message="Failed to load tags"
            description={error}
            showIcon
            style={{ marginBottom: 16 }}
          />
        )}
        <Table<TagWithStats>
          rowKey={(record) => `${record.id}`}
          columns={columns}
          dataSource={filteredTags}
          loading={loading}
          pagination={{ pageSize: 20 }}
        />
      </Card>
    </Space>
  );
};

export default SubsystemDetailPage;
